from html.parser import HTMLParser
import urllib.request
class Paragraphs(HTMLParser):
    def __init__(self): super().__init__(); self.parts=None; self.paragraphs=[]; self.script=False
    def handle_starttag(self, tag, attrs):
        if tag == 'script': self.script=True
        if tag == 'p': self.parts=[]
    def handle_endtag(self, tag):
        if tag == 'script': self.script=False
        if tag == 'p' and self.parts is not None:
            self.paragraphs.append(''.join(self.parts)); self.parts=None
    def handle_data(self, text):
        if self.parts is not None and not self.script: self.parts.append(text)
for member, team, region in [('Alice','Design','us-east'),('Bob','Support','eu-west'),('Guest','Community','global')]:
    headers={} if member=='Guest' else {'Cookie':f'member={member}; team={team}', 'x-region':region}
    with urllib.request.urlopen(urllib.request.Request('http://localhost:3015/',headers=headers)) as response:
