        expected=[f'Welcome, {member}',f'Team: {team}',f'Region: {region}','12 active projects']
        assert response.status==200 and all(text in parser.paragraphs for text in expected), (response.status,parser.paragraphs)
        print(member, response.status, parser.paragraphs)
print('Per-request details and shared totals verified')
